// h2 с прозрачным фолбэком на h1
const srv = http2.createSecureServer({ key, cert: fullchain, allowHTTP1: true }); srv.on('stream', (stream, headers) => { stream.respond({ ':status': 200 }); stream.end('h2'); }); srv.on('request', (req, res) => { res.end('h1'); }); // срабатывает лишь при ALPN 'http/1.1'
ALPN — расширение TLS ClientHello: клиент анонсирует ['h2','http/1.1'], сервер выбирает один, и выбранный протокол известен в момент завершения рукопожатия — без лишней задержки. allowHTTP1 заставляет тот же listener отвечать старым клиентам без второго порта.
